// Five realistic events in the exact shape the Zapier step sends.
// __sample lets these skip the secret check; real webhook calls can't set a top-level field.
const c = (first, last, email, phone) => ({ id: 'zm-' + first.toLowerCase(), first_name: first, last_name: last, email, phone, address: '1450 Larimer St', zip: '80202' });
const events = [
  { event: 'booking_created', customer: c('Maria', 'Lopez', 'maria.lopez@example.com', '+17205550101'), appointment: { id: 'apt-101', date: '2026-10-21', service: 'Deep Clean', status: 'Scheduled', price: 260 } },
  { event: 'appointment_status_updated', customer: c('Maria', 'Lopez', 'maria.lopez@example.com', '+17205550101'), appointment: { id: 'apt-101', date: '2026-10-21', service: 'Deep Clean', status: 'Completed', price: 260 } },
  { event: 'invoice_paid', customer: c('Maria', 'Lopez', 'maria.lopez@example.com', '+17205550101'), invoice: { id: 'inv-5531', amount: 260 } },
  { event: 'recurring_service_created', customer: c('James', 'Carter', 'j.carter@example.com', '+13035550188'), appointment: { id: 'rec-77', date: '2026-10-24', service: 'Standard Clean · every 2 weeks', status: 'Scheduled', price: 165 } },
  { event: 'recurring_service_cancelled', customer: c('Priya', 'Nair', 'priya.nair@example.com', '+17205550144'), appointment: { id: 'rec-41', service: 'Standard Clean · weekly', status: 'Cancelled' } },
];
return events.map((body) => ({ json: { __sample: true, headers: {}, body } }));

// =====================================================================
//  CONFIG: the only node you need to edit.
// =====================================================================
const CONFIG = {
  dryRun: true,                         // true = build every GHL call but don't send it (see "Preview")
  sharedSecret: '__CHANGE_ME__',        // Zapier sends this in the x-tcs-secret header
  ghlApiBase: 'https://services.leadconnectorhq.com',
  locationId: '__GHL_LOCATION_ID__',    // Settings → Business Profile, or the id in the sub-account URL
  salesPipelineName: 'Cleaning Sales',  // matched by name, so you never paste stage IDs
  // Optional: GHL custom field IDs (Settings → Custom Fields → copy the field id). Leave '' to skip.
  customFieldIds: { zenmaidCustomerId: '', lastCleanDate: '' },
  completedStatuses: ['completed', 'complete', 'done', 'finished'],
  sheetId: '',                          // Google Sheet id of the TCS Weekly Report file; '' = don't log
  logTab: 'ZenMaid Log',
};
// ---------------------------------------------------------------------
return $input.all().map((i) => ({ json: { config: CONFIG, input: i.json } }));

// Validates the request and turns one ZenMaid event into a plan of GHL changes.
// Pure rules, no API calls, so the dry run shows exactly what would happen.
const cfg = $json.config;
const input = $json.input || {};
const headers = input.headers || {};
const body = input.body || {};
const fromSample = input.__sample === true;

const reject = (reason) => ({ json: { valid: false, reason, event: body.event || '' } });
if (!fromSample && (!cfg.sharedSecret || cfg.sharedSecret === '__CHANGE_ME__' || headers['x-tcs-secret'] !== cfg.sharedSecret)) {
  return reject('Missing or wrong x-tcs-secret header');
}

const ev = String(body.event || '').toLowerCase().trim().replace(/[\s-]+/g, '_');
const cu = body.customer || {};
const ap = body.appointment || {};
const inv = body.invoice || {};
const email = String(cu.email || '').trim().toLowerCase();
const phone = String(cu.phone || '').trim();
if (!email && !phone) return reject('Customer has no email or phone, so GHL cannot match a contact');

const status = String(ap.status || '').toLowerCase().trim();
const completed = cfg.completedStatuses.includes(status);
const money = (v) => { const n = Number(String(v ?? '').replace(/[^0-9.\-]/g, '')); return Number.isFinite(n) ? n : 0; };

// event → tags, opportunity stage, opportunity status, log row?
const RULES = {
  customer_created:            { tags: ['zenmaid-customer'] },
  booking_created:             { tags: ['zenmaid-customer', 'zenmaid-booked'], stage: 'Booked in ZenMaid', oppStatus: 'won', log: true },
  one_time_service_created:    { tags: ['zenmaid-customer', 'zenmaid-booked'], stage: 'Booked in ZenMaid', oppStatus: 'won', log: true },
  recurring_service_created:   { tags: ['zenmaid-customer', 'recurring-client'], stage: 'Recurring Client', oppStatus: 'won', log: true },
  recurring_service_cancelled: { tags: ['recurring-cancelled'], log: true },
  appointment_status_updated:  completed ? { tags: ['job-completed'], log: true, lastClean: true } : { tags: [], log: status === 'cancelled' || status === 'canceled' },
  invoice_paid:                { tags: [], log: true },
};
const rule = RULES[ev];
if (!rule) return reject(`Unknown event "${body.event}". Expected one of: ${Object.keys(RULES).join(', ')}`);

const customFields = [];
if (cfg.customFieldIds.zenmaidCustomerId && cu.id) customFields.push({ id: cfg.customFieldIds.zenmaidCustomerId, field_value: String(cu.id) });
if (cfg.customFieldIds.lastCleanDate && rule.lastClean && ap.date) customFields.push({ id: cfg.customFieldIds.lastCleanDate, field_value: String(ap.date) });

const contact = {
  locationId: cfg.locationId,
  firstName: cu.first_name || undefined,
  lastName: cu.last_name || undefined,
  email: email || undefined,
  phone: phone || undefined,
  address1: cu.address || undefined,
  postalCode: cu.zip ? String(cu.zip) : undefined,
  source: 'ZenMaid',
  ...(customFields.length ? { customFields } : {}),
};

const name = [cu.first_name, cu.last_name].filter(Boolean).join(' ') || email || phone;
const logRow = rule.log ? {
  'Received At': DateTime.now().setZone('America/Denver').toISO({ suppressMilliseconds: true }),
  'Event': ev,
  'Customer': name,
  'Email': email,
  'Phone': phone,
  'Appointment Date': ap.date || '',
  'Service': ap.service || '',
  'Status': ap.status || (ev === 'invoice_paid' ? 'Paid' : ''),
  'Amount': ev === 'invoice_paid' ? money(inv.amount) : money(ap.price),
  'Invoice ID': inv.id || '',
  'Appointment ID': ap.id || '',
  'ZenMaid Customer ID': cu.id || '',
} : null;

return { json: {
  valid: true,
  event: ev,
  name,
  plan: {
    contact,
    tags: rule.tags,
    stage: rule.stage || null,
    oppStatus: rule.oppStatus || 'open',
    oppName: `${name} · ${ap.service || 'Cleaning'}`,
    monetaryValue: money(ap.price),
    logRow,
  },
} };

// Shows exactly what live mode would send to GHL and Google Sheets for this event.
const cfg = $('Config').first().json.config;
const p = $json.plan;
const calls = [
  { step: 'Upsert contact', method: 'POST', url: `${cfg.ghlApiBase}/contacts/upsert`, body: p.contact },
];
if (p.tags.length) calls.push({ step: 'Add tags', method: 'POST', url: `${cfg.ghlApiBase}/contacts/{contactId}/tags`, body: { tags: p.tags } });
if (p.stage) calls.push({ step: `Opportunity → "${p.stage}" (${p.oppStatus}) in "${cfg.salesPipelineName}"`, method: 'PUT or POST', url: `${cfg.ghlApiBase}/opportunities/…` });
if (p.logRow) calls.push({ step: cfg.sheetId ? `Append row to "${cfg.logTab}"` : 'Log row (skipped: no sheetId)', row: p.logRow });
return { json: { dryRun: true, event: $json.event, customer: $json.name, calls } };

const id = $json.contact?.id || $json.id;
if (!id) throw new Error('GHL upsert returned no contact id: ' + JSON.stringify($json).slice(0, 300));
const n = $('Normalize & Plan').item.json;
return { json: { contactId: id, isNew: $json.new === true, event: n.event, name: n.name, plan: n.plan } };

// Finds the pipeline + stage by name, then decides: move the contact's open deal, or create one.
const cfg = $('Config').first().json.config;
const c = $('Carry Plan').item.json;
const pipes = $('GHL · Pipelines').item.json.pipelines || [];
const pipe = pipes.find((p) => p.name.trim().toLowerCase() === cfg.salesPipelineName.toLowerCase());
if (!pipe) throw new Error(`Pipeline "${cfg.salesPipelineName}" not found. Have: ${pipes.map((p) => p.name).join(', ')}`);
const stage = (pipe.stages || []).find((s) => s.name.trim().toLowerCase() === c.plan.stage.toLowerCase());
if (!stage) throw new Error(`Stage "${c.plan.stage}" not found in "${pipe.name}". Have: ${(pipe.stages || []).map((s) => s.name).join(', ')}`);

const opps = ($json.opportunities || []).filter((o) => o.pipelineId === pipe.id);
const existing = opps.find((o) => o.status === 'open') || opps[0];
const base = cfg.ghlApiBase;
const body = { pipelineId: pipe.id, pipelineStageId: stage.id, status: c.plan.oppStatus };
if (c.plan.monetaryValue) body.monetaryValue = c.plan.monetaryValue;

return { json: existing
  ? { ...c, method: 'PUT', url: `${base}/opportunities/${existing.id}`, body }
  : { ...c, method: 'POST', url: `${base}/opportunities/`, body: { ...body, locationId: cfg.locationId, contactId: c.contactId, name: c.plan.oppName } } };

// The Config node doesn't run in an error execution, so the alert address lives here.
const ALERT_TO = '__YOUR_EMAIL__';
const e = $input.first().json;
const node = e.execution?.lastNodeExecuted || e.trigger?.error?.node?.name || 'unknown';
const msg = String(e.execution?.error?.message || e.trigger?.error?.message || 'Unknown error').slice(0, 600);
return [{ json: {
  to: ALERT_TO,
  subject: `Automation error: ${e.workflow?.name || 'ZenMaid sync'} (${node})`,
  html: `<p><b>Workflow:</b> ${e.workflow?.name}<br><b>Failed node:</b> ${node}<br><b>Error:</b> ${msg}</p>` +
        (e.execution?.url ? `<p><a href="${e.execution.url}">Open the execution</a></p>` : ''),
} }];
